INSERT INTO public.activities (activity_id, activity_name, selectable_in_onboarding, mandatory, minimum_sessions_per_week, primary_metrics, description) VALUES
  ('walking', 'Walking', TRUE, FALSE, FALSE, 'distance_km,duration_min,intensity', 'Low-impact cardiovascular activity that can progress through duration, distance and pace.'),
  ('running', 'Running', TRUE, FALSE, FALSE, 'distance_km,duration_min,intervals,intensity', 'Running progression can use run-walk, easy continuous, interval and tempo sessions.'),
  ('cycling', 'Cycling', TRUE, FALSE, FALSE, 'distance_km,duration_min,intervals,intensity', 'Cycling progresses through duration, distance and controlled interval sessions.'),
  ('swimming', 'Swimming', TRUE, FALSE, FALSE, 'distance_m,duration_min,intervals,rest_seconds', 'Swimming progresses through total distance, technique work and interval sets.'),
  ('strength', 'Full Body Strength', FALSE, TRUE, 2, 'sets,reps,rest_seconds,variation_level', 'Mandatory full-body strength training performed twice per week.')
INSERT INTO public.workout_templates (template_id, activity_id, session_type, title, intensity_default, warmup_description, main_description, cooldown_description) VALUES
  ('WALK_EASY', 'walking', 'easy', 'Easy Walk', 'easy', 'Begin with 3-5 minutes of relaxed walking. Gradually lengthen your stride and settle into a comfortable rhythm.', 'Walk at a comfortable conversational pace. Keep posture upright, shoulders relaxed and take controlled natural steps.', 'Finish with 3-5 minutes of slower walking and allow breathing to return toward normal.'),
  ('WALK_BRISK', 'walking', 'brisk', 'Brisk Walk', 'moderate', 'Walk easily for about 5 minutes before gradually increasing pace.', 'Walk faster than your normal pace while staying controlled. Arms may swing naturally. You should still be able to speak in short sentences.', 'Reduce the pace gradually for approximately 5 minutes.'),
  ('WALK_INTERVAL', 'walking', 'interval', 'Brisk Walking Intervals', 'moderate', 'Walk easily for 5-7 minutes.', 'Alternate brisk walking periods with easier recovery walking. Do not sprint. The goal is controlled changes in pace.', 'Walk slowly for approximately 5 minutes.'),
  ('RUN_WALK', 'running', 'run_walk', 'Run-Walk Session', 'easy', 'Begin with 5-8 minutes of brisk walking. Add a few short periods of very easy jogging if comfortable.', 'Alternate easy running with walking recovery. Running portions should feel controlled rather than like a sprint.', 'Finish with at least 5 minutes of easy walking.'),
  ('RUN_EASY', 'running', 'easy', 'Easy Continuous Run', 'easy', 'Walk or jog easily for 5-8 minutes before settling into the main run.', 'Run at a comfortable conversational effort. Focus on relaxed shoulders, controlled breathing and an easy sustainable pace.', 'Slow to an easy jog and then walk for approximately 5 minutes.'),
  ('RUN_INTERVAL', 'running', 'interval', 'Running Interval Session', 'moderate_hard', 'Complete 8-10 minutes of easy walking and jogging before beginning the intervals.', 'Alternate controlled faster running periods with easy walking or jogging recovery. Faster does not mean all-out sprinting.', 'Jog or walk easily for 5-8 minutes.'),
  ('RUN_TEMPO', 'running', 'tempo', 'Controlled Tempo Run', 'moderate', 'Complete approximately 8-10 minutes of easy walking and jogging.', 'Run at a comfortably challenging but controlled pace. The effort should be clearly harder than an easy run but should not become an all-out effort.', 'Finish with easy jogging or walking for 5-10 minutes.'),
  ('CYCLE_EASY', 'cycling', 'easy', 'Easy Cycling', 'easy', 'Cycle very easily for the first 5 minutes.', 'Maintain a comfortable cadence and resistance. The effort should feel sustainable and smooth.', 'Reduce resistance and pedal easily for approximately 5 minutes.'),
  ('CYCLE_STEADY', 'cycling', 'steady', 'Steady Cycling', 'moderate', 'Cycle easily for 5-8 minutes.', 'Ride at a steady moderate effort. Keep the pedalling rhythm controlled and avoid turning the session into an all-out effort.', 'Pedal easily for approximately 5 minutes.'),
  ('CYCLE_INTERVAL', 'cycling', 'interval', 'Cycling Intervals', 'moderate_hard', 'Cycle easily for 8-10 minutes.', 'Alternate stronger controlled cycling efforts with easy pedalling recovery periods.', 'Finish with at least 5 minutes of easy cycling.'),
  ('SWIM_EASY', 'swimming', 'easy', 'Easy Swim', 'easy', 'Begin with several relaxed lengths using a comfortable stroke.', 'Swim at a controlled pace with emphasis on smooth technique and comfortable breathing.', 'Finish with several very easy relaxed lengths.'),
  ('SWIM_TECHNIQUE', 'swimming', 'technique', 'Swimming Technique Session', 'easy', 'Begin with easy relaxed swimming.', 'Break the total distance into manageable sets. Prioritize stroke control, body position and relaxed breathing over speed.', 'Finish with relaxed easy swimming.'),
  ('SWIM_INTERVAL', 'swimming', 'interval', 'Swimming Interval Session', 'moderate_hard', 'Begin with easy swimming and several relaxed practice lengths.', 'Divide the distance into repeated controlled efforts separated by recovery at the pool wall. Maintain technique as intensity rises.', 'Finish with relaxed swimming.'),
  ('STRENGTH_FULL_BODY', 'strength', 'full_body', 'Full Body Strength Session', 'moderate', 'Begin with 5-8 minutes of easy movement. Include shoulder circles, controlled bodyweight squats, gentle hip movement and easy marching.', 'Perform the five prescribed exercises in order. Prioritize controlled technique over speed or heavy resistance.', 'Finish with easy walking and relaxed mobility for the muscles used during the session.')
INSERT INTO public.exercise_variations (variation_id, exercise_family, variation_name, difficulty_level, equipment, description, form_cues) VALUES
  ('SQUAT_L1', 'squat', 'Chair Squat', TRUE, 'chair', 'Stand in front of a stable chair with feet about shoulder-width apart. Push the hips back and lower under control until lightly touching the chair, then stand again.', 'Keep the chest upright; knees follow the direction of the toes; keep both feet planted.'),
  ('SQUAT_L2', 'squat', 'Bodyweight Squat', 2, NULL, 'Stand with feet approximately shoulder-width apart. Sit the hips back and bend the knees, then drive through the feet to stand.', 'Keep the torso controlled; knees track with the toes; move through a comfortable range.'),
  ('SQUAT_L3', 'squat', 'Loaded Squat', 3, 'dumbbell, backpack, water bottles or other secure household resistance', 'Perform the squat while holding a manageable external load close to the body.', 'Use only a secure load; maintain the same controlled squat technique used in the bodyweight version.'),
  ('LUNGE_L1', 'lunge', 'Supported Reverse Lunge', TRUE, 'stable chair or support', 'Hold a stable support and step one foot backward. Lower under control and return to standing before changing legs.', 'Keep the front foot planted; stay controlled; use the support for balance rather than pulling.'),
  ('LUNGE_L2', 'lunge', 'Reverse Lunge', 2, NULL, 'Step backward into a controlled lunge, then push through the front foot to return to standing.', 'Maintain balance; keep the front knee tracking with the toes; control both the lowering and return.'),
  ('LUNGE_L3', 'lunge', 'Loaded Reverse Lunge', 3, 'dumbbells, water bottles or secure household resistance', 'Perform reverse lunges while holding a manageable external load.', 'Use a secure load and preserve the same balance and knee control as the unloaded variation.'),
  ('PUSHUP_L1', 'pushup', 'Wall Push-Up', TRUE, 'wall', 'Place both hands against a wall around chest height. Bend the elbows and bring the chest toward the wall, then press away.', 'Keep the body in a straight line; avoid letting the hips collapse forward.'),
  ('PUSHUP_L2', 'pushup', 'Incline Push-Up', 2, 'stable bench, table or other secure raised surface', 'Place hands on a stable elevated surface and perform a push-up while maintaining a straight body position.', 'Use only a stable surface; keep elbows controlled; maintain trunk tension.'),
  ('PUSHUP_L3', 'pushup', 'Floor Push-Up', 3, NULL, 'From a strong plank position, lower the chest toward the floor and press back to the starting position.', 'Keep head, torso and hips aligned; maintain controlled elbows and trunk position.'),
  ('CURL_L1', 'bicep_curl', 'Light Bottle Bicep Curl', TRUE, 'small water bottles or light dumbbells', 'Hold a light object securely in each hand. Bend the elbows to bring the load upward, then lower slowly.', 'Keep elbows close to the body and avoid swinging the torso.'),
  ('CURL_L2', 'bicep_curl', 'Standard Bicep Curl', 2, 'dumbbells, filled water bottles or other secure resistance', 'Curl a manageable resistance while keeping the upper arms relatively still.', 'Avoid momentum; control the lowering phase.'),
  ('CURL_L3', 'bicep_curl', 'Heavier Controlled Bicep Curl', 3, 'dumbbells or secure household resistance', 'Use a slightly greater resistance while maintaining strict controlled curl technique.', 'Increase resistance only if previous resistance can be controlled without swinging.'),
  ('ROW_L1', 'supported_row', 'Light Supported One-Arm Row', TRUE, 'stable support and light water bottle', 'Place one hand on a stable support. Hold a light weight in the opposite hand and pull it toward the side of the rib cage, then lower slowly.', 'Keep the back controlled; avoid twisting the torso; pull the elbow backward.'),
  ('ROW_L2', 'supported_row', 'Supported One-Arm Row', 2, 'stable support plus dumbbell, bottle or secure household resistance', 'Use a supported stance and row a manageable load toward the torso.', 'Maintain a stable trunk and controlled shoulder movement.'),
  ('ROW_L3', 'supported_row', 'Heavier Supported One-Arm Row', 3, 'stable support and heavier secure resistance', 'Perform the same supported rowing motion with a greater but manageable resistance.', 'Do not sacrifice trunk position or range of motion simply to use more resistance.')
